-- Foundation Studio · Snowflake execution SQL
-- foundation:stage 2
CREATE OR REPLACE TABLE OGFS_DEMO.GOLD.fact_test_result AS SELECT b.test_result_key,b.lab_sample_key,d2.material_sk AS material_sk,d3.test_method_sk AS test_method_sk,b.date_key,b.result_value,b.result_unit,b.spec_lower_limit,b.spec_upper_limit,b.within_spec FROM (SELECT test_result_key,lab_sample_key,test_method_key,material_key,TO_NUMBER(TO_CHAR(TRY_TO_TIMESTAMP_NTZ(TO_VARCHAR(result_date)),'YYYYMMDD')) date_key,result_value,result_unit,spec_lower_limit,spec_upper_limit,within_spec,TRY_TO_TIMESTAMP_TZ(result_date) _event_time FROM OGFS_DEMO.SILVER.conformed_test_result) b LEFT JOIN OGFS_DEMO.GOLD.dim_material d2 ON d2.material_key=b.material_key AND b._event_time >= d2.valid_from AND b._event_time < d2.valid_to LEFT JOIN OGFS_DEMO.GOLD.dim_test_method d3 ON d3.test_method_key=b.test_method_key AND b._event_time >= d3.valid_from AND b._event_time < d3.valid_to;
